CREATE TABLE "PerfilAcesso" ("id" TEXT NOT NULL PRIMARY KEY, "nome" TEXT NOT NULL, "descricao" TEXT, "sistema" TEXT, "permissoes" JSONB NOT NULL DEFAULT '{}', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "PerfilAcesso_nome_key" ON "PerfilAcesso"("nome");
CREATE UNIQUE INDEX "PerfilAcesso_sistema_key" ON "PerfilAcesso"("sistema");
ALTER TABLE "Usuario" ADD COLUMN "perfilAcessoId" TEXT, ADD COLUMN "permissoesPersonalizadas" JSONB NOT NULL DEFAULT '{}', ADD COLUMN "sessaoVersao" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "excluidoEm" TIMESTAMP(3);
ALTER TABLE "Usuario" ADD CONSTRAINT "Usuario_perfilAcessoId_fkey" FOREIGN KEY ("perfilAcessoId") REFERENCES "PerfilAcesso"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
INSERT INTO "PerfilAcesso" ("id", "nome", "descricao", "sistema", "updatedAt") VALUES ('perfil-administrador', 'Administrador', 'Acesso completo. Perfil protegido do sistema.', 'ADMINISTRADOR', CURRENT_TIMESTAMP), ('perfil-equipe', 'Equipe atual', 'Preserva os acessos operacionais dos usuários existentes.', 'EQUIPE_LEGADA', CURRENT_TIMESTAMP);
UPDATE "Usuario" SET "perfilAcessoId" = CASE WHEN admin THEN 'perfil-administrador' ELSE 'perfil-equipe' END;
CREATE TABLE "HistoricoAcesso" ("id" TEXT NOT NULL PRIMARY KEY, "autorId" TEXT NOT NULL, "entidade" TEXT NOT NULL, "entidadeId" TEXT NOT NULL, "acao" TEXT NOT NULL, "antes" JSONB, "depois" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "HistoricoAcesso_entidade_entidadeId_createdAt_idx" ON "HistoricoAcesso"("entidade", "entidadeId", "createdAt");

UPDATE "PerfilAcesso" SET "permissoes" = '{"fornecedores":["visualizar","editar","adicionar","excluir"],"insumos":["visualizar","editar","adicionar","excluir"],"compras":["visualizar","editar","adicionar","excluir"],"compras.receber":["visualizar","editar"],"notas":["visualizar","adicionar","editar"],"notas.manifestar":["visualizar","editar"],"inventario":["visualizar","editar","adicionar","excluir"],"inventario.contagem":["visualizar","editar","adicionar","excluir"],"inventario.entrada":["visualizar","adicionar"],"inventario.perdas":["visualizar","adicionar","excluir"],"financeiro.dre":["visualizar"],"financeiro.fluxo":["visualizar"],"financeiro.movimentacoes":["visualizar","editar","adicionar","excluir"],"financeiro.baixas":["visualizar","editar"],"financeiro.bancario":["visualizar","editar","adicionar","excluir"],"financeiro.plano":["visualizar","editar","adicionar","excluir"],"vendas":["visualizar"],"crm":["visualizar"],"producao":["visualizar"],"rh":["visualizar"],"patrimonio":["visualizar"]}'::jsonb WHERE "id" = 'perfil-equipe';
